function calculator(){const d=fin.settings.calculatorDefaults||{};setTimeout(calcLive,0);return `<div class="card"><div class="section-head"><div><h2>محاسبه‌گر سود</h2><p class="muted">سناریوی سریع و مستقل از اطلاعات ثبت‌شده</p></div><button class="btn" onclick="finSaveCalculatorDefaults()">ذخیره به‌عنوان پیش‌فرض</button></div><div class="form-grid">${[['Sales','فروش ماهانه',d.sales],['PurchasePercent','مواد اولیه / خرید (% فروش)',d.purchasePercent],['Payroll','حقوق',d.payroll],['Rent','اجاره',d.rent],['Management','مدیریت',d.management],['Utilities','قبوض',d.utilities],['Maintenance','تعمیر و نگهداری',d.maintenance],['Other','سایر هزینه‌ها',d.other||0],['VatPercent','ارزش افزوده %',d.vatPercent??fin.settings.vatPercent],['TaxPercent','مالیات عملکرد %',d.performanceTaxPercent??fin.settings.performanceTaxPercent]].map(([k,l,v])=>`<div class="field"><label>${l}</label><input id="fcalc${k}" type="number" value="${N(v)}" oninput="finCalcLive()"></div>`).join('')}</div></div><div id="finCalcResult"></div>`}
function calcValues(){const g=k=>N(document.getElementById('fcalc'+k)?.value),sales=g('Sales'),purchase=sales*g('PurchasePercent')/100,payroll=g('Payroll'),fixed=g('Rent')+g('Management')+g('Utilities')+g('Maintenance')+g('Other'),tax=sales*(g('VatPercent')+g('TaxPercent'))/100,profit=sales-purchase-payroll-fixed-tax,variableRate=(g('PurchasePercent')+g('VatPercent')+g('TaxPercent'))/100,breakEven=(1-variableRate)>0?(payroll+fixed)/(1-variableRate):0;return{sales,purchase,payroll,fixed,tax,profit,breakEven,margin:sales?profit/sales*100:0}}
function calcLive(){const r=calcValues(),el=document.getElementById('finCalcResult');if(!el)return;el.innerHTML=`<div class="grid grid-4"><div class="card kpi"><div class="label">هزینه مواد</div><div class="value">${F(r.purchase)}</div></div><div class="card kpi"><div class="label">مالیات‌ها</div><div class="value">${F(r.tax)}</div></div><div class="card kpi"><div class="label">سود تقریبی</div><div class="value ${r.profit<0?'danger-text':'positive'}">${F(r.profit)}</div><div class="sub">${r.margin.toFixed(1)}٪ فروش</div></div><div class="card kpi"><div class="label">فروش سربه‌سر</div><div class="value">${F(r.breakEven)}</div></div></div>`}
async function saveCalcDefaults(){const d=fin.settings.calculatorDefaults=fin.settings.calculatorDefaults||{};d.sales=N(document.getElementById('fcalcSales')?.value);d.purchasePercent=N(document.getElementById('fcalcPurchasePercent')?.value);d.payroll=N(document.getElementById('fcalcPayroll')?.value);d.rent=N(document.getElementById('fcalcRent')?.value);d.management=N(document.getElementById('fcalcManagement')?.value);d.utilities=N(document.getElementById('fcalcUtilities')?.value);d.maintenance=N(document.getElementById('fcalcMaintenance')?.value);d.other=N(document.getElementById('fcalcOther')?.value);d.vatPercent=N(document.getElementById('fcalcVatPercent')?.value);d.performanceTaxPercent=N(document.getElementById('fcalcTaxPercent')?.value);await save('ذخیره پیش‌فرض محاسبه‌گر')}
function settings(){return `<div class="card"><div class="section-head"><h2>تنظیمات مالی</h2><button class="btn btn-primary" onclick="finSaveSettings()">ذخیره</button></div><div class="form-grid"><div class="field"><label>ارزش افزوده (% فروش)</label><input id="finVat" type="number" value="${fin.settings.vatPercent}"></div><div class="field"><label>مالیات عملکرد (% فروش)</label><input id="finTax" type="number" value="${fin.settings.performanceTaxPercent}"></div><div class="field"><label>حساب ذخیره مالیات</label><select id="finTaxReserve">${financeAccountOptions(fin.settings.taxReserveAccountId)}</select></div><div class="field"><label>شروع حساب ذخیره مالیات (سال/ماه)</label><input id="finTaxStart" data-raw-number="1" value="${E(taxStartKey())}" placeholder="1405/07"></div><div class="field full"><label>دسته‌های بدهی و طلب — هر مورد در یک خط</label><textarea id="finObCats">${E(A(fin.settings.obligationCategories).join('\n'))}</textarea></div><div class="field full"><label>دسته‌های هزینه — هر مورد در یک خط (دسته‌های استاندارد مثل تبلیغات، غذای پرسنلی و شوینده همیشه در فرم ثبت هزینه پیشنهاد می‌شوند)</label><textarea id="finExpCats">${E(A(fin.settings.expenseCategories).join('\n'))}</textarea></div><div class="field full"><label>دسته‌های درآمد — هر مورد در یک خط</label><textarea id="finIncCats">${E(A(fin.settings.incomeCategories).join('\n'))}</textarea></div></div></div>`}
async function saveSettings(){fin.settings.vatPercent=N(document.getElementById('finVat')?.value);fin.settings.performanceTaxPercent=N(document.getElementById('finTax')?.value);fin.settings.taxReserveAccountId=S(document.getElementById('finTaxReserve')?.value);const taxStart=S(document.getElementById('finTaxStart')?.value).replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d));if(taxStart&&!/^\d{4}\/\d{2}$/.test(taxStart))return toast('شروع حساب مالیات را به شکل ۱۴۰۵/۰۷ وارد کنید',true);fin.settings.taxStartMonth=taxStart;fin.settings.obligationCategories=S(document.getElementById('finObCats')?.value).split('\n').map(S).filter(Boolean);fin.settings.expenseCategories=S(document.getElementById('finExpCats')?.value).split('\n').map(S).filter(Boolean);fin.settings.incomeCategories=S(document.getElementById('finIncCats')?.value).split('\n').map(S).filter(Boolean);await save('ذخیره تنظیمات مالی');renderView()}
/* Monthly cost forecast vs actual. Forecast = HR lines (hrForecastMonth over the HR payload) + fixed-cost estimates; saving a month freezes its forecast so month-end actuals are compared against what was expected. */
const COST_FIXED_DEFAULTS=[['rent','اجاره'],['water','آب'],['electricity','برق'],['gas','گاز'],['ads','تبلیغات'],['phone','تلفن']];
function costState(){ensure();const cf=fin.costForecast=fin.costForecast&&typeof fin.costForecast==='object'?fin.costForecast:{};if(!Array.isArray(cf.fixedLines))cf.fixedLines=COST_FIXED_DEFAULTS.map(([key,label])=>({key,label,amount:0,category:label}));cf.hrCategories=cf.hrCategories&&typeof cf.hrCategories==='object'?cf.hrCategories:{hrFood:'غذای پرسنل',hrInsurance:'بیمه'};cf.months=A(cf.months);return cf}
function costMonth(y,m){return costState().months.find(x=>+x.year===+y&&+x.month===+m)||null}
function liveCostForecast(y,m){const cf=costState(),hrm=support.hr&&typeof hrForecastMonth==='function'?hrForecastMonth(support.hr,y,m):null,lines=[...(hrm?hrm.lines.map(l=>({key:l.key,label:l.label,amount:Math.round(N(l.amount)),group:'hr'})):[]),...cf.fixedLines.map(l=>({key:l.key,label:S(l.label)||'بدون عنوان',amount:N(l.amount),group:'fixed'}))];return{lines,total:lines.reduce((s,l)=>s+l.amount,0),hr:hrm}}
function costClosure(y,m){return A(support.hr?.payrollClosures).filter(c=>+c.year===+y&&+c.month===+m&&c.active!==false).sort((a,b)=>S(b.finalizedAt).localeCompare(S(a.finalizedAt)))[0]||null}
// Same month rule as the P&L (monthCalc): an expense counts in its expense month, spread over spreadMonths.
function costCategoryActual(category,y,m){if(!S(category))return null;const rows=A(fin.entries).filter(e=>e.type==='expense'&&active(e)&&e.entryType!=='opening'&&!e.obligationId&&!e.sourcePaymentId&&S(e.category)===S(category)).map(e=>({e,share:entryShare(e,y,m)})).filter(x=>x.share);return rows.length?{amount:Math.round(rows.reduce((s,x)=>s+x.share,0)),count:rows.length,category:S(category)}:null}
function costAutoActual(line,y,m){const cf=costState();if(line.group==='fixed'){const c=costCategoryActual(cf.fixedLines.find(l=>l.key===line.key)?.category,y,m);return c?{amount:c.amount,source:`${F(c.count)} هزینه «${c.category}»`}:null}
 const cat=costCategoryActual(cf.hrCategories[line.key],y,m),catNote=cat?` + ${F(cat.count)} هزینه «${cat.category}»`:'';if(line.key==='hrInsurance')return cat?{amount:cat.amount,source:catNote.slice(3)}:null;
 const closure=costClosure(y,m);if(!closure)return cat?{amount:cat.amount,source:`فقط${catNote.slice(2)}؛ حقوق ماه قطعی نشده`}:null;
 const rows=A(closure.rows),sum=f=>rows.reduce((s,r)=>s+f(r),0),base={hrSalary:()=>sum(r=>N(r.wage)+N(r.overtime)+N(r.fixed)+N(r.otherPayment)+N(r.returnAidAmount)),hrTransport:()=>sum(r=>N(r.transport)),hrFood:()=>sum(r=>N(r.mealAllowance)),hrBonus:()=>sum(r=>N(r.reward))}[line.key];
 return base?{amount:base()+(cat?.amount||0),source:'سند قطعی حقوق'+catNote}:cat?{amount:cat.amount,source:catNote.slice(3)}:null}
function costComparison(y,m){const saved=costMonth(y,m),live=liveCostForecast(y,m),frozen=A(saved?.forecast?.lines),base=frozen.length?frozen.map(l=>({...l})):live.lines.map(l=>({...l}));live.lines.forEach(l=>{if(!base.some(x=>x.key===l.key))base.push({...l,amount:0,addedAfterSnapshot:true})});
 const lines=base.map(l=>{const manual=saved?.actuals?.[l.key],hasManual=manual!==undefined&&manual!==null&&manual!=='',auto=costAutoActual(l,y,m),actual=hasManual?N(manual):auto?auto.amount:null,amount=N(l.amount);return{...l,amount,auto,manual:hasManual?N(manual):'',actual,diff:actual===null?null:actual-amount,pct:actual===null||!amount?null:(actual-amount)/amount*100}}),withActual=lines.filter(l=>l.actual!==null);
 return{saved,live,frozen:frozen.length>0,lines,forecastTotal:lines.reduce((s,l)=>s+l.amount,0),actualTotal:withActual.reduce((s,l)=>s+l.actual,0),comparedForecast:withActual.reduce((s,l)=>s+l.amount,0),missing:lines.length-withActual.length}}
function costDiffCell(d,pct){if(d===null)return'<td>—</td><td>—</td>';const cls=d>0?'danger-text':d<0?'positive':'';return`<td class="num ${cls}">${d>0?'+':''}${F(d)}</td><td class="${cls}">${pct===null?'—':`${pct>0?'+':''}${pct.toFixed(1)}٪`}</td>`}
function costForecastView(){const y=ui.year,m=ui.month,cf=costState(),c=costComparison(y,m),hr=c.live.hr,s=support.hr?.settings||{},diff=c.actualTotal-c.comparedForecast,groups=[['hr','نیروی انسانی'],['fixed','هزینه‌های ثابت']],cats=A(fin.settings.expenseCategories);
 const row=l=>`<tr><td>${E(l.label)}${l.addedAfterSnapshot?' <small class="muted">(پس از ثبت پیش‌بینی اضافه شد)</small>':''}</td><td class="num">${F(l.amount)}</td><td>${l.auto?`${F(l.auto.amount)}<br><small class="muted">${E(l.auto.source)}</small>`:'<small class="muted">—</small>'}</td><td><input type="number" min="0" step="1" id="cfActual_${E(l.key)}" data-cost-actual="${E(l.key)}" value="${l.manual===''?'':N(l.manual)}" placeholder="${l.auto?'خالی = خودکار':'مبلغ واقعی'}" style="max-width:150px"></td><td class="num"><b>${l.actual===null?'—':F(l.actual)}</b></td>${costDiffCell(l.diff,l.pct)}</tr>`;
 return filter()+`<div class="grid grid-4"><div class="card kpi"><div class="label">پیش‌بینی هزینه ماه</div><div class="value">${F(c.forecastTotal)}</div><div class="sub">${c.frozen?`ثبت‌شده ${E(c.saved.forecast.savedAt?new Date(c.saved.forecast.savedAt).toLocaleDateString('fa-IR'):'')}`:'زنده — هنوز ثبت نشده'}</div></div><div class="card kpi"><div class="label">هزینه واقعی ثبت‌شده</div><div class="value">${F(c.actualTotal)}</div><div class="sub">${F(c.lines.length-c.missing)} از ${F(c.lines.length)} ردیف</div></div><div class="card kpi"><div class="label">اختلاف با پیش‌بینی</div><div class="value ${diff>0?'danger-text':diff<0?'positive':''}">${diff>0?'+':''}${F(diff)}</div><div class="sub">فقط ردیف‌های دارای مبلغ واقعی${c.comparedForecast?` — ${(diff/c.comparedForecast*100).toFixed(1)}٪`:''}</div></div><div class="card kpi"><div class="label">ردیف بدون مبلغ واقعی</div><div class="value">${F(c.missing)}</div><div class="sub">در پایان ماه تکمیل شود</div></div></div>
 ${hr?'':'<div class="notice danger">اطلاعات پرسنل بارگذاری نشد؛ ردیف‌های نیروی انسانی محاسبه نشده و ثبت پیش‌بینی ممکن نیست.</div>'}${hr?.warningCount?`<div class="notice warning">${F(hr.warningCount)} نفر اطلاعات توافق حقوق ناقص دارند؛ جزئیات در جدول نیروی انسانی پایین صفحه. <a href="personnel.html?view=personnel">اصلاح در توافق حقوق پرسنل</a></div>`:''}${c.frozen&&Math.abs(c.live.total-A(c.saved.forecast.lines).reduce((t,l)=>t+N(l.amount),0))>1?`<div class="hint">پیش‌بینی زنده با اطلاعات فعلی ${M(c.live.total)} است؛ برای جایگزینی «به‌روزرسانی پیش‌بینی» را بزنید.</div>`:''}
 <div class="card"><div class="section-head"><div><h2>پیش‌بینی و هزینه واقعی ماه</h2><p class="muted">اول ماه پیش‌بینی را ثبت کنید تا ثابت بماند. پایان ماه مبلغ واقعی خودکار از سند قطعی حقوق و «سایر پرداخت‌ها» با دسته هم‌نام پر می‌شود؛ هر ردیف را می‌توان دستی جایگزین کرد. افزایش هزینه قرمز است.</p></div><div><button class="btn" ${hr?'':'disabled'} onclick="finCostSnapshot()">${c.frozen?'به‌روزرسانی پیش‌بینی ثبت‌شده':'ثبت پیش‌بینی این ماه'}</button> <button class="btn btn-primary" onclick="finCostSaveActuals()">ذخیره هزینه‌های واقعی</button></div></div><div class="table-wrap"><table class="data-table" data-no-cell-unit="1"><thead><tr><th>ردیف هزینه</th><th>پیش‌بینی</th><th>واقعی خودکار</th><th>واقعی دستی</th><th>واقعی نهایی</th><th>اختلاف</th><th>٪</th></tr></thead><tbody>${groups.map(([g,label])=>{const ls=c.lines.filter(l=>l.group===g);return ls.length?`<tr><th colspan="7">${label} — پیش‌بینی ${M(ls.reduce((t,l)=>t+l.amount,0))}</th></tr>${ls.map(row).join('')}`:''}).join('')}</tbody><tfoot><tr><th>جمع</th><th class="num">${F(c.forecastTotal)}</th><th></th><th></th><th class="num">${F(c.actualTotal)}</th>${costDiffCell(c.missing===c.lines.length?null:diff,c.comparedForecast?diff/c.comparedForecast*100:null)}</tr></tfoot></table></div><div class="field full"><label>یادداشت ماه</label><textarea id="cfNotes">${E(c.saved?.notes||'')}</textarea></div><div class="hint">همه مبالغ به تومان است. خرید مواد اولیه و مالیات در «سود و زیان» هستند و در این پیش‌بینی نیستند.</div></div>
 ${hr?`<details class="card"><summary><b>جزئیات پیش‌بینی نیروی انسانی</b> <small class="muted">— ${F(hr.rows.length)} نفر فعال، از «توافق حقوق» هر نفر</small></summary><div class="table-wrap" style="margin-top:10px"><table class="data-table" data-no-cell-unit="1"><thead><tr><th>پرسنل</th><th>شیفت</th><th>ساعت</th><th>حقوق و مزایا</th><th>رفت‌وآمد</th><th>غذا و صبحانه</th><th>بیمه کارفرما</th><th>کل هزینه</th><th>هشدار</th></tr></thead><tbody>${hr.rows.map(r=>`<tr><td>${E(r.personnelId)} | ${E(r.name)}</td><td>${F(r.shifts)}</td><td>${F(r.hours)}</td><td class="num">${F(r.wage+r.fixedAllowance+r.returnAid)}</td><td class="num">${F(r.transport)}</td><td class="num">${F(r.staffFood)}</td><td class="num">${F(r.employerInsurance)}</td><td class="num"><b>${F(r.hrCost)}</b></td><td>${r.warnings.length?`<small class="danger-text">${r.warnings.map(E).join('، ')}</small>`:''}</td></tr>`).join('')||'<tr><td colspan="9" class="empty">پرسنل فعالی نیست.</td></tr>'}</tbody></table></div><div class="hint">صبحانه آخر هفته سایر پرسنل: ${F(hr.weekendBreakfastCount)} وعده = ${M(hr.weekendBreakfast)} — پاداش برآوردی: ${M(hr.bonus)}. پارامترها: بهای هر وعده غذا ${M(s.preparedMealCost)}، صبحانه ${M(s.breakfastCost)}، ${F(s.overnightBreakfastNights??30)} صبحانه ماهانه هر شب‌خواب. <a href="settings.html?view=settings">ویرایش در تنظیمات حقوق</a></div></details>`:''}
 <details class="card" ${c.lines.some(l=>l.group==='fixed'&&l.amount>0)?'':'open'}><summary><b>برآورد هزینه‌های ثابت و دسته‌های هزینه واقعی</b></summary><datalist id="cfCats">${cats.map(x=>`<option value="${E(x)}">`).join('')}</datalist><div class="table-wrap" style="margin-top:10px"><table class="data-table" data-no-cell-unit="1"><thead><tr><th>عنوان</th><th>برآورد ماهانه (تومان)</th><th>دسته هزینه برای مبلغ واقعی</th><th></th></tr></thead><tbody>${cf.fixedLines.map(l=>`<tr data-cost-line="${E(l.key)}"><td><input data-f="label" value="${E(l.label)}"></td><td><input data-f="amount" type="number" min="0" step="1" value="${N(l.amount)}"></td><td><input data-f="category" list="cfCats" value="${E(l.category||'')}" placeholder="بدون خودکار"></td><td><button class="btn btn-sm btn-danger" onclick="finCostRemoveLine('${E(l.key)}')">حذف</button></td></tr>`).join('')}<tr><td>غذای پرسنلی (هزینه واقعی تکمیلی)</td><td class="muted">از پرسنل</td><td><input id="cfCatFood" list="cfCats" value="${E(cf.hrCategories.hrFood||'')}"></td><td></td></tr><tr><td>بیمه (پرداخت واقعی)</td><td class="muted">از پرسنل</td><td><input id="cfCatInsurance" list="cfCats" value="${E(cf.hrCategories.hrInsurance||'')}"></td><td></td></tr></tbody></table></div><div class="hint">مبلغ واقعی هر ردیف = جمع «سایر پرداخت‌ها»ی این ماه با همین دسته. اگر دسته‌ای در فهرست نیست، از تنظیمات مالی اضافه کنید.</div><div><button class="btn" onclick="finCostAddLine()">+ ردیف هزینه</button> <button class="btn btn-primary" onclick="finCostSaveSettings()">ذخیره برآوردها</button></div></details>`}
function costReadSettingsInputs(){const cf=costState(),rows=[...document.querySelectorAll('[data-cost-line]')];if(!rows.length)return true;const lines=[];for(const r of rows){const g=f=>r.querySelector(`[data-f="${f}"]`)?.value,label=S(g('label')),amount=N(g('amount'));if(amount<0){toast('برآورد نمی‌تواند منفی باشد',true);return false}lines.push({...(cf.fixedLines.find(l=>l.key===r.dataset.costLine)||{}),key:r.dataset.costLine,label,amount,category:S(g('category'))})}cf.fixedLines=lines;if(document.getElementById('cfCatFood'))cf.hrCategories={...cf.hrCategories,hrFood:S(document.getElementById('cfCatFood').value),hrInsurance:S(document.getElementById('cfCatInsurance').value)};return true}
function costAddLine(){if(!costReadSettingsInputs())return;const cf=costState();cf.fixedLines.push({key:`fx${Date.now().toString(36)}`,label:'',amount:0,category:''});renderView()}
function costRemoveLine(key){if(!costReadSettingsInputs())return;const cf=costState();cf.fixedLines=cf.fixedLines.filter(l=>l.key!==key);renderView()}
async function costSaveSettings(){const before=snapshot();if(!costReadSettingsInputs())return;if(costState().fixedLines.some(l=>!l.label))return toast('عنوان همه ردیف‌ها الزامی است',true);try{await save('ذخیره برآورد هزینه‌های ثابت');renderView()}catch(e){restore(before);toast(e.message,true)}}
async function costSnapshot(){const y=ui.year,m=ui.month,live=liveCostForecast(y,m);if(!live.hr)return toast('اطلاعات پرسنل بارگذاری نشده است',true);const existing=costMonth(y,m);if(existing?.forecast&&!confirm(`پیش‌بینی ثبت‌شده این ماه (${M(A(existing.forecast.lines).reduce((t,l)=>t+N(l.amount),0))}) با پیش‌بینی فعلی (${M(live.total)}) جایگزین شود؟ نسخه قبلی در سابقه می‌ماند.`))return;const before=snapshot(),cf=costState();let rec=existing;if(!rec){rec={year:y,month:m,actuals:{},notes:''};cf.months.push(rec)}if(rec.forecast)rec.previousForecasts=[...A(rec.previousForecasts),rec.forecast].slice(-10);rec.forecast={lines:live.lines.map(({key,label,amount,group})=>({key,label,amount,group})),total:live.total,hrPeople:live.hr.rows.length,savedAt:now(),savedBy:typeof currentAuthUserV5!=='undefined'?S(currentAuthUserV5):''};try{await save(`ثبت پیش‌بینی هزینه ${y}/${m}`);renderView()}catch(e){restore(before);toast(e.message,true)}}
async function costSaveActuals(){const y=ui.year,m=ui.month,inputs=[...document.querySelectorAll('[data-cost-actual]')],actuals={};for(const el of inputs){const v=S(el.value);if(v==='')continue;const x=N(v);if(x<0)return toast('مبلغ واقعی نمی‌تواند منفی باشد',true);actuals[el.dataset.costActual]=x}const before=snapshot(),cf=costState();let rec=costMonth(y,m);if(!rec){rec={year:y,month:m,actuals:{},notes:''};cf.months.push(rec)}rec.actuals=actuals;rec.notes=S(document.getElementById('cfNotes')?.value);rec.updatedAt=now();try{await save(`ثبت هزینه واقعی ${y}/${m}`);renderView()}catch(e){restore(before);toast(e.message,true)}}
function view(){if(!finLoaded){load();return `<div class="card empty">در حال بارگذاری اطلاعات مالی…</div>`}if(loadError||!fin)return `<div class="card empty"><h2>اطلاعات مالی بارگذاری نشد</h2><p>${E(loadError)}</p><button class="btn btn-primary" onclick="finRefresh()">تلاش دوباره</button></div>`;const body=ui.tab==='opening'?openingView():ui.tab==='obligations'?obligationsHome():ui.tab==='payables'?obligationList('payable'):ui.tab==='receivables'?obligationList('receivable'):ui.tab==='checks'?checksView():ui.tab==='forecast'?costForecastView():ui.tab==='entries'?entries():ui.tab==='calculator'?calculator():ui.tab==='settings'?(location.replace(FIN_SETTINGS_URL),'<div class="card empty">در حال انتقال به تنظیمات نرم‌افزار…</div>'):monthly();setTimeout(()=>RayoJalali?.mark?.(),0);return (typeof pageHead==='function'?pageHead('امور مالی','بدهی‌ها، مطالبات، چک‌ها، سود و زیان و سایر دریافت و پرداخت‌ها؛ دفتر پیگیری داخلی، بدون اتصال بانکی و جایگزین حسابداری رسمی نیست'):'')+tabs()+body}
